import{_ as s,a as i,c as e,ac as t}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"Kafka：分区、位移与交付边界","description":"以分区和消费组模型解释生产确认、提交与重放。","frontmatter":{"title":"Kafka：分区、位移与交付边界","description":"以分区和消费组模型解释生产确认、提交与重放。","showdocs":{"topics":[{"id":"kafka","title":"Kafka","link":"/topics/kafka/"}],"kind":"知识专题","scope":"general","audience":"general","group":"数据库与存储","seriesTitle":"KAFKA 实践课程","summary":"以分区和消费组模型解释生产确认、提交与重放。","status":"active","related":[{"title":"Kafka：完整订单生产消费 CLI","link":"/middleware/messaging/kafka/plus/practice/project","kind":"完整实践","scope":"general","audience":"general"},{"title":"Kafka：位移、积压与恢复练习","link":"/middleware/messaging/kafka/operations","kind":"知识专题","scope":"general","audience":"general"},{"title":"Kafka：KRaft 起步与命令","link":"/middleware/messaging/kafka/base/basic/start","kind":"知识专题","scope":"general","audience":"general"}],"prev":{"text":"Kafka：KRaft 起步与命令","link":"/middleware/messaging/kafka/base/basic/start"},"next":{"text":"Kafka：完整订单生产消费 CLI","link":"/middleware/messaging/kafka/plus/practice/project"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Kafka：KRaft 起步与命令","link":"/middleware/messaging/kafka/base/basic/start"},"next":{"text":"Kafka：完整订单生产消费 CLI","link":"/middleware/messaging/kafka/plus/practice/project"}},"headers":[],"relativePath":"middleware/messaging/kafka/delivery-model.md","filePath":"middleware/messaging/kafka/delivery-model.md"}'),p={name:"middleware/messaging/kafka/delivery-model.md"};function n(r,a,k,l,h,o){return i(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="kafka-分区、位移与交付边界" tabindex="-1">Kafka：分区、位移与交付边界 <a class="header-anchor" href="#kafka-分区、位移与交付边界" aria-label="Permalink to &quot;Kafka：分区、位移与交付边界&quot;">​</a></h1><h2 id="part-1" tabindex="-1">分区、键、位移与消费组 <a class="header-anchor" href="#part-1" aria-label="Permalink to &quot;分区、键、位移与消费组 {#part-1}&quot;">​</a></h2><blockquote><p>本轮仅静态审阅，以下命令与练习均未执行；预期结果不是本轮运行证据。早期真实服务验证仅为历史记录，不能代替当前环境验证。</p></blockquote><h3 id="part-1-partition" tabindex="-1">topic 与 partition <a class="header-anchor" href="#part-1-partition" aria-label="Permalink to &quot;topic 与 partition {#part-1-partition}&quot;">​</a></h3><p>前置：完成 <a href="/middleware/messaging/kafka/base/basic/start#commands">起步</a>。topic 是一类日志的名字，partition 是独立追加的有序日志。offset 是一条记录在某个分区中的位置；不同分区的 offset 不能拿来比较先后。消息不会因为消费成功就立即从 Kafka 删除。</p><p>本实验三个分区、一个副本。生产时明确 --partition 0/1/2 可以观察每个分区的 offset 从 0 增长；这用于测试分区覆盖，并非推荐业务把分区号硬编码。分区内有序不表示整个 topic 全局有序。并行处理同一分区的任务也可能使业务完成顺序变化。</p><h3 id="part-1-key" tabindex="-1">key 与顺序 <a class="header-anchor" href="#part-1-key" aria-label="Permalink to &quot;key 与顺序 {#part-1-key}&quot;">​</a></h3><p>没有显式指定分区时，驱动按 key 选择分区。相同 key、相同分区数和相同分区算法通常会落在同一分区，因此 customer-1 的事件可以保持分区内顺序。增加分区数或改变客户端分区算法可能改变映射。跨 Python、Java 客户端迁移时不能只凭“都使用 key”就假设相同分区。</p><div class="language-sh vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/kafka/main.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --topic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> key-orders</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/kafka/main.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --topic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> key-orders</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> produce</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --key</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> customer-1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --value</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> created</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/kafka/main.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --topic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> key-orders</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> produce</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --key</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> customer-1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --value</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> paid</span></span></code></pre></div><p>预期两条结果 partition 相同、offset 递增。value 是 UTF-8 字符串，本项目不添加 Schema Registry；真实演进应约定字段版本、编码和兼容策略，避免消费者突然无法解析新数据。</p><h3 id="part-1-group" tabindex="-1">group 与提交位置 <a class="header-anchor" href="#part-1-group" aria-label="Permalink to &quot;group 与提交位置 {#part-1-group}&quot;">​</a></h3><p>同一消费组中的成员分摊分区，同一时刻一个分区分给组内一个成员；成员多于分区会有空闲成员。不同 group.id 有独立位移，因此 accounting 和 audit 各读一遍同一日志，这是广播业务能力的基础。加入、退出和失去心跳会触发分区重分配，不能把一次 assignment 当永久归属。</p><p>消费组提交下一条的读取位置（即下一个要读取的 offset），而不是最后一条已处理记录的位置。例如处理分区 0 的 offset 7 后提交 8。我们的 commit(message=message) 由驱动计算加一，避免手工把 7 当恢复位置。enable.auto.commit=false 与 enable.auto.offset.store=false 都显式设置，处理结束后才同步提交。</p><h3 id="part-1-replay" tabindex="-1">未提交重放与恢复 <a class="header-anchor" href="#part-1-replay" aria-label="Permalink to &quot;未提交重放与恢复 {#part-1-replay}&quot;">​</a></h3><p>未提交重放指同一消费组恢复时重新读取尚未提交的记录。新 topic 写入三条消息，各分区一条；同一新组先消费而不加 --commit，再消费并提交，第二次应该看到相同内容和分区 offset。随后再写入 after-commit，同组应只读取新记录。历史验证器设计为直接比较消息内容与分区 offset，不以进程退出作为提交成功的证明。</p><div class="language-sh vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/kafka/main.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --topic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> key-orders</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> consume</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --group</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> accounting</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --count</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/kafka/main.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --topic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> key-orders</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> consume</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --group</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> accounting</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --count</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --commit</span></span></code></pre></div><p>这里沿用前节全新 key-orders 的两条记录，且 accounting 尚无提交，因此 count=2。若 topic 已有旧数据，应换新名重做生产，不能假定固定数量；跨分区返回列表也不保证全局顺序。没有有效提交才由 auto.offset.reset=earliest 决定从头开始，已有提交不会因 earliest 而重读。读取数量不足在期限结束返回非零，避免把空列表误当成功。</p><p>本篇的机制与失败分支可按<a href="/middleware/messaging/kafka/operations#part-2-exercise">综合练习</a>书面推演；提示与<a href="/middleware/messaging/kafka/operations#part-2-answer">参考答案</a>分开提供，无需执行示例。</p><h2 id="part-2" tabindex="-1">确认、重试与保留 <a class="header-anchor" href="#part-2" aria-label="Permalink to &quot;确认、重试与保留 {#part-2}&quot;">​</a></h2><blockquote><p>本轮仅静态审阅，以下命令与练习均未执行；预期结果不是本轮运行证据。早期真实服务验证仅为历史记录，不能代替当前环境验证。</p></blockquote><h3 id="part-2-acks" tabindex="-1">producer 的交付边界 <a class="header-anchor" href="#part-2-acks" aria-label="Permalink to &quot;producer 的交付边界 {#part-2-acks}&quot;">​</a></h3><p>produce 只是把消息排入客户端缓冲区。完整程序启用 enable.idempotence=true、acks=all，并在 delivery callback 收集 broker 结果，再检查 flush 剩余数量；任一交付错误或未排空都返回非零。acks=all 等待当前 ISR 参与确认，实际可靠性还取决于副本数和 min.insync.replicas；本实验单副本不具备节点失效冗余。</p><p>幂等生产者可以消除同一生产者会话内协议重试造成的部分重复，但客户端重启后重新提交同一订单仍可能是新消息。不能据此宣称业务端到端 exactly-once。订单号等业务键与外部数据库唯一约束仍有价值。</p><h3 id="part-2-commit" tabindex="-1">consumer 提交与副作用 <a class="header-anchor" href="#part-2-commit" aria-label="Permalink to &quot;consumer 提交与副作用 {#part-2-commit}&quot;">​</a></h3><p>消费提交必须以业务副作用的完成为边界。先提交再做业务，进程故障可能漏处理；先做业务再提交，故障后可能重复处理。这份 CLI 将完整消费批次的 JSON 输出并 flush 视为可观察实验效果，达到 count 且输出成功后才逐条同步提交；批次不足超时不输出且不提交。真实应用应先持久化业务结果，再提交位移，配合幂等键/去重表；外部数据库写入和 Kafka 提交通常不是同一个原子事务。输出之后提交失败时即使 stdout 有内容仍返回非零，下一次可能重放，接收结果的一方仍须处理重复。</p><p>批量提交可降低请求开销，却增加故障后的重放范围。不要异步启动业务任务后立刻提交尚未完成的消息，也不要对一个分区提交超过尚未处理成功的 offset。跨分区各有进度，不应把最大 offset 当成所有分区进度。</p><h3 id="part-2-retention" tabindex="-1">积压、保留与压缩 <a class="header-anchor" href="#part-2-retention" aria-label="Permalink to &quot;积压、保留与压缩 {#part-2-retention}&quot;">​</a></h3><p>积压 lag 通常按分区观察日志末尾与组已提交位置之差，同时看记录速率、消息大小和处理时延。组重分配、提交间隔和事务可见性都会影响指标解释，lag=0 不证明下游业务结果正确。保留策略按时间/大小回收日志段，消费者落后太久可能失去待处理数据。</p><div class="language-sh vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> showdocs-m4b-kafka-broker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/kafka/bin/kafka-configs.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bootstrap-server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> broker:9092</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --entity-type</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> topics</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --entity-name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orders</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --describe</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> showdocs-m4b-kafka-broker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/kafka/bin/kafka-consumer-groups.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bootstrap-server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> broker:9092</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --group</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> accounting</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --describe</span></span></code></pre></div><p>retention.ms 是日志保留配置，不能当精确的单条消息定时器；实际删除还受 segment 滚动和清理调度影响。cleanup.policy=compact 保留每个 key 的最新状态，压缩异步运行，不等于队列消费确认，也不能用来保证所有历史事件长期可回放。不要为做练习随意缩短共享 topic 保留时间。</p><h3 id="part-2-retry" tabindex="-1">失败后的选择 <a class="header-anchor" href="#part-2-retry" aria-label="Permalink to &quot;失败后的选择 {#part-2-retry}&quot;">​</a></h3><p>临时网络错误由有界生产重试处理；永久业务解析失败则需要记录 topic/partition/offset、原始内容与原因，暂停该分区或发送独立失败 topic 并定义补偿规则。无限原地重试会卡住整个分区，跳过并提交又可能永久丢弃业务。本课程不虚构通用重试次数，也没有实现跨系统事务或自动死信框架。</p><p>失败练习把目标改成 127.0.0.1:1，预期在 message.timeout.ms=5000 消息到期后交付失败，进程返回 1；消息期限不保证进程精确五秒退出。不要因为 produce 没立即抛异常就判定消息成功写入。</p><p>本篇的机制与失败分支可按<a href="/middleware/messaging/kafka/operations#part-2-exercise">综合练习</a>书面推演；提示与<a href="/middleware/messaging/kafka/operations#part-2-answer">参考答案</a>分开提供，无需执行示例。</p>`,34)])])}const F=s(p,[["render",n]]);export{c as __pageData,F as default};
